/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	return {
		event: 'Application Card',
		value: {
			applicationName: api.context.props.payload.name,
            businessObjectiveName: api.context.props.payload.businessObjective.businessObjectiveName,
            page: 'adoption-blueprint-details',
			appStatus: api.state.installationStatusHighlightedValue.label,
			appLicensingStatus: api.state.licenseStatusHighlightedValue.label
		}
	};
}
